    // research & discovery flow, NavAssist format, from the project PDFs
    discovery: [{"title": "Research Objectives", "lead": ["The research aimed to understand why urban dog parents find it hard to trust a boarding service, and what would help them leave their dog with confidence."], "listLead": "The study focused on:", "list": ["Understanding how dog parents choose a boarding service today.", "Identifying the safety, hygiene and care concerns behind their anxiety.", "Understanding what updates parents want while their dog is away.", "Exploring how kennel managers and caretakers handle care and communication.", "Identifying opportunities to build trust between pet parents and kennels."]}, {"title": "Understanding the Problem", "lead": ["Urban dog parents in India lack access to a reliable and verified boarding network. Most existing options are unregulated, with no standard protocols for care, hygiene or safety.", "The absence of real-time updates or proof of activity during a pet’s stay is felt most by working professionals and frequent travellers, who cannot monitor their dog’s well-being from afar."], "note": ["The result", "Anxiety and distrust make it difficult for pet owners to confidently leave their dogs in someone else’s care."]}, {"title": "Primary Research Findings", "lead": ["An online survey of pet parents across Pune, Mumbai and Bengaluru, and interviews with boarding users and kennel staff, explored how dogs are boarded today and what worries their owners."], "stats": true, "gallery": true, "rows": [["Updates Bring Reassurance", "85%+ of pet parents prefer receiving photos, videos and updates during boarding."], ["Verification Decides the Choice", "75% consider verified staff and clean facilities essential before choosing a service."], ["Leaving a Pet Causes Anxiety", "70%+ of urban dog owners feel anxious leaving pets for boarding due to safety and care concerns."], ["Kennels Lack Trained Support", "60%+ of kennels lack trained staff or proper medical support, affecting service quality."]], "note": ["Key takeaway", "Trust comes from verification before the stay and visibility during it."]}, {"title": "From Research to Insights", "lead": ["The research revealed recurring needs across the boarding experience."], "insights": [["Trust starts before booking", "Parents need proof of verified staff, hygiene and reviews before they choose a kennel."], ["Silence creates anxiety", "Without photos and updates, parents worry about their dog for the whole stay."], ["Care details need one home", "Feeding, medication and behaviour notes must stay together and be easy to find."], ["Kennel staff need structure too", "Managers and caretakers need organised tasks to keep care consistent."]]}, {"title": "Defining Design Opportunities", "lead": ["Based on the research findings, the project identified five opportunities to make boarding more transparent for pet parents and easier to run for kennels."], "rows": [["Verify Every Kennel", "List kennels with reviews, certifications and amenities."], ["Make the Right Kennel Easy to Find", "Search by location, availability, dog size and special needs."], ["Keep Each Dog’s Needs in One Profile", "Feeding instructions, medications, allergies and behaviour notes."], ["Share the Stay as It Happens", "Photo and video updates, with immediate alerts if there is an issue."], ["Organise the Kennel Team", "Structured tasks for managers and caretakers."]]}],
    cs: {"theme": {"bg": "#F4F1F8", "dark": "#2A1D45", "soft": "#E8E0F4", "acc": "#6C46A9", "cards": ["#ECE5F6", "#FFEDB5", "#EAE4DA"]}, "role": "UX Research & UI/UX Design", "type": "Service design · Mobile", "hmw": "How might we help dog parents choose a kennel they trust and stay connected while they are away?", "researchHead": "What dog parents worry about when they travel.", "researchSub": "A survey of pet parents across Pune, Mumbai and Bengaluru, interviews with owners and kennel staff, and card sorting.", "directionHead": "Build trust before, during and after the stay.", "direction": [["Verified care", "Kennels, staff and facilities are verified and reviewed.", "i-check"], ["Live visibility", "Photos, videos and updates arrive throughout the stay.", "i-img"], ["Every need noted", "Feeding, medication and behaviour live in one dog profile.", "i-layout"]], "flow": ["Find a verified kennel", "Share your dog’s needs", "Stay updated"], "experienceHead": "Everything a dog parent needs, from booking to pickup.", "experienceSub": "Verified listings, detailed dog profiles, live updates and emergency alerts in one app.", "iaHead": "Card sorting with pet parents shaped the structure.", "closing": ["Less worry on the road.", "More trust at the kennel."], "style": {"colours": [["#6C46A9", "Purple", "Primary"], ["#FFC93E", "Sunny yellow", "Secondary"], ["#F7F4EF", "Cream", "Background"], ["#9A9A9A", "Grey", "Secondary text"], ["#3E3E3E", "Charcoal", "Text"]], "type": [["Open Sans", "H1 32 Semibold · H2 22 · Body 16 · Small 12", "Popular kennels"]], "grid": {"cols": 4, "margin": 30, "gutter": 16, "device": "Mobile", "w": 428}}, "keyFeatures": [["Verified kennel listings", "Trusted kennels with reviews, certifications and amenities."], ["Advanced search & filters", "Location, availability, dog size and special needs."], ["Dog profile", "Feeding, medication, allergies and behaviour notes."], ["Booking & payments", "Transparent booking for short and long stays."], ["Live updates", "Photo and video updates and wellness check-ins."], ["Chat with staff", "Talk to the caretakers directly."], ["Emergency alerts", "Immediate notification if there’s an issue."], ["Ratings & reviews", "Honest feedback from other pet parents."]], "study": {"head": "Tree testing showed where the structure confused people.", "stats": [["02", "tree-testing tasks"], ["04", "learnability trials"], ["21", "clicks to book"]], "areas": ["Find the epilepsy medication schedule", "See today’s photo update", "Book a stay end to end"], "findings": [["Medication lived in the wrong place", "People looked under Communication instead of Pet Profile, so the labels were refined."], ["Updates needed a home of their own", "People searched Communication for photos, so Updates became its own top-level branch."], ["Faster with every try", "Task time fell from about 30 s to about 22 s across four trials, then levelled out."]], "noFlow": true}, "featuresHead": "The Core of the Experience", "interfaceHead": "The final interface"},
