    personas: [{"avatar": "av-male", "lines": {"Goals": "He wants to bring dignity and fair income to the weaver’s journey, widen market access for his community and protect traditional techniques.", "Pain points": "Machine-made lookalikes crowd the market while he has limited access to ethical buyers and little recognition for his work.", "Interests": "He enjoys mentoring young weavers, simplifying his team’s workload and following market trends on social media."}, "img": "tar-artisan", "name": "Gulzar Ahmad", "age": "38", "role": "Manager & master weaver · Chandauli", "bio": "Gulzar is a veteran weaver from the Ansari community, introduced to the loom as a child. Today he leads a team of 150+ artisans, managing everything from design to distribution. While rooted in craft, his days are equally filled with paperwork, mentoring and quiet advocacy for fair wages and recognition.", "quotes": ["Weaving isn’t just work, it’s legacy.", "We need fair pay, not just praise.", "Technology should support, not replace us.", "Is anyone even noticing the hands behind the weave?"], "cols": [["Interests", "i-comp", ["Mentoring youth in life and craft.", "Simplifying his team’s workload.", "Following market trends on social media."]], ["Pain points", "i-comment", ["A market saturated with machine-made lookalikes.", "Limited direct access to ethical buyers.", "Not getting recognition for his work."]], ["Goals", "i-pin", ["Build dignity and fair income into the weaver’s journey.", "Expand market access for his community.", "Document and protect traditional techniques."]]]}, {"avatar": "av-male", "lines": {"Goals": "He wants to build a strong, authentic craft brand that gives artisans visibility and dignity and stands alongside niche players.", "Pain points": "Powerloom imitations undercut his prices, and a tight budget makes it hard to balance authenticity with modern branding and e-commerce.", "Interests": "He is drawn to textile history and heritage crafts, digital marketing and collaborating with artisans at craft expos."}, "img": "tar-yaseen", "name": "Mohammad Yaseen", "age": "65", "role": "Owner of Taranaksh · Varanasi", "bio": "An 11th-generation weaver from the Ansari community, Yaseen manages 400 looms and supports 800 artisans. His workshop blends traditional handlooms with modern tools to craft Banarasi sarees, lehengas and dupattas using Murshidabad silk. Committed to preserving the legacy, he mentors young weavers through on-site training.", "quotes": ["Authenticity matters more than trends.", "Our story needs to reach beyond Varanasi.", "Quality can’t be compromised for speed.", "Will the next generation carry this forward?"], "cols": [["Interests", "i-comp", ["Textile history and heritage crafts.", "Digital marketing and branding.", "Collaborating with artisans and craft expos."]], ["Pain points", "i-comment", ["Powerloom imitations undercut pricing.", "A tight budget for e-commerce and storytelling.", "Balancing authenticity with modern branding."]], ["Goals", "i-pin", ["Build a strong, authentic craft brand.", "Empower artisans with visibility and dignity.", "Position the brand alongside niche players."]]]}, {"avatar": "av-female", "lines": {"Goals": "She wants to own a few timeless handcrafted sarees and discover fashion rooted in heritage while supporting local artisans.", "Pain points": "She can’t always tell real handloom from imitations, doesn’t understand the pricing and hesitates to buy expensive sarees online.", "Interests": "She loves indie fashion, styling and storytelling, festive and wedding saree moments and India’s textile scene."}, "img": "tar-meher", "name": "Meher", "age": "26", "role": "Marketing associate · Delhi", "bio": "Meher is a young marketing professional who loves dressing up for festivals and weddings in unique, meaningful attire. While she lives a fast-paced urban life, she is drawn to slow fashion and handcrafted stories. Banarasi sarees remind her of her mom’s collection, but she is looking for ways to make them feel her own.", "quotes": ["I love the idea of supporting artisans, if only I knew who they were.", "I wish brands told more stories instead of just showing products.", "It’s so hard to tell what’s real and what’s machine-made.", "Is this saree really worth ₹30,000?"], "cols": [["Interests", "i-comp", ["Indie fashion, styling content and storytelling.", "Festivals, weddings and saree moments.", "India’s textile scene."]], ["Pain points", "i-comment", ["Can’t always tell real handloom from imitations.", "Unsure why some sarees are so expensive.", "Hesitates to buy expensive handloom online."]], ["Goals", "i-pin", ["Own a few timeless handcrafted sarees.", "Discover meaningful fashion rooted in heritage.", "Support local artisans and sustainable practice."]]]}],
    personaMore: {"age": "38 years old", "role": "Veteran weaver, Ansari community", "bio": "Gulzar is a veteran weaver from the Ansari community, introduced to the loom as a child. Today he leads a team of 150+ artisans, managing everything from design to distribution. While rooted in craft, his days are equally filled with paperwork, mentoring and quiet advocacy for fair wages and recognition.", "cols": [["Interests", "i-comp", ["Mentoring youth in life and craft.", "Finding new ways to simplify his team’s workload.", "Keeping up with market trends through social media."]], ["Pain points", "i-comment", ["A market saturated with machine-made lookalikes.", "Bridging traditional methods with modern demand.", "Not getting recognition for his work."]], ["Goals", "i-pin", ["Build dignity and fair income into the weaver’s journey.", "Expand market access for his community.", "Document and protect traditional weaving techniques."]]]},
