    discovery: [{"title": "Research Objectives", "lead": ["The research aimed to understand the Banarasi handloom craft, the artisans behind it and why its value is not reaching buyers."], "listLead": "The study focused on:", "list": ["Talking to artisans about their background, the craft’s history and its process.", "Understanding the making of a Banarasi saree in detail.", "Observing and documenting the problems faced by the artisans and the craft.", "Understanding what buyers need to trust a handloom purchase.", "Identifying opportunities to connect buyers directly with verified artisans."]}, {"title": "Understanding the Problem", "lead": ["Banarasi silk sarees are among India’s most celebrated textiles, known for their rich fabric, intricate weaving and deep cultural significance, often passed down through generations as heirloom pieces.", "Today the craft faces imitation products, declining artisan visibility and reduced appreciation among younger audiences."], "note": ["The result", "Financial hardship for artisans, low awareness among buyers and a slow loss of the culture and tradition behind the craft."]}, {"title": "Primary Research Findings", "lead": ["A ten-day field study in weaving homes and workshops in Varanasi documented the craft and the problems its artisans face."], "rows": [["Low Wages", "Skilled artisans earn very little compared to market price."], ["Invisible Creators", "Most weavers remain unnamed, working in cramped homes."], ["Women in the Shadows", "Many women contribute silently, yet often go uncredited."], ["Declining Youth Interest", "Younger generations avoid the profession due to low income."], ["No Ownership or Credit", "Artisans lack control over their pricing and brand identity."], ["Craft in Crisis", "Endangered by mass production and fast fashion, leading to undervaluation."]], "note": ["Key takeaway", "The value of the craft is hidden: buyers cannot see who made a saree or verify that it is genuine."]}, {"title": "From Research to Insights", "lead": ["The research revealed what buyers need before they value and trust handloom."], "insights": [["Trust and authenticity come first", "Trust and authenticity are essential for handloom buyers."], ["Stories add value", "Emotional storytelling adds value to premium purchases."], ["Clear categories help buyers", "Categorising sarees by fabric, motif and price gives buyers clarity."], ["Impact must feel personal", "Impact messaging must feel personal, not performative."]]}, {"title": "Competitive Analysis", "lead": ["Existing handloom and craft brands were benchmarked to see how they present authenticity and the people behind the product."], "names": ["Tilfi", "Kasturi Creations", "Sacred Weaves", "Raw Mango", "Fabindia", "Okhai", "Taneira"], "note": ["Opportunity identified", "None of the seven brands benchmarked had artisan profiles. That gap became the heart of Taranaksh."]}, {"title": "Defining Design Opportunities", "lead": ["Based on the research findings, the project identified four opportunities to bring buyers and artisans closer."], "rows": [["Transparent Authenticity System", "Certification badges, verified artisan profiles, QR codes and “Story Behind the Saree” videos build credibility and trust."], ["Immersive Storytelling Experience", "Documentary-style process videos, craft storytelling pages, blogs and social integration bring the craft to life."], ["Artisan-First Digital Empowerment", "Direct-to-customer model, name-tagged products, revenue transparency and personalised artisan storefronts."], ["Craft Continuity and Youth Recognition", "Fellowships, Weaver of the Month features, innovation showcases and youth-led campaigns encourage future participation."]]}],
